import os
import sys
import json
import re
from decimal import Decimal

FACT_CONFIG = {
    "performance start": {
        "doc": "usaspending_awards",
        "path": "period_of_performance.start_date",
        "type": "date"
    },
    "performance end": {
        "doc": "usaspending_awards",
        "path": "period_of_performance.end_date",
        "type": "date"
    },
    "amount obligated": {
        "doc": "usaspending_awards",
        "path": "total_obligation",
        "type": "amount"
    },
    "potential value": {
        "doc": "usaspending_awards",
        "path": "base_and_all_options",
        "type": "amount"
    }
}


def get_nested(obj, path):
    parts = path.split('.')
    cur = obj
    for p in parts:
        if isinstance(cur, dict):
            cur = cur.get(p)
        else:
            return None
    return cur


def format_date(val):
    if val is None:
        return None
    val = str(val).strip()
    if not val:
        return None
    m = re.match(r'^(\d{4}-\d{2}-\d{2})', val)
    if m:
        return m.group(1)
    return val


def format_amount(val):
    if val is None:
        return None
    if isinstance(val, (int, float, Decimal)):
        return str(val)
    val = str(val).strip()
    if not val:
        return None
    cleaned = val.replace('$', '').replace(',', '').strip()
    if not cleaned:
        return None
    return cleaned


def amounts_equal(a1, a2):
    try:
        d1 = Decimal(a1)
        d2 = Decimal(a2)
        return d1 == d2
    except Exception:
        return a1 == a2


def dates_equal(d1, d2):
    return d1 == d2


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    if not os.path.exists(awards_file):
        for fname in os.listdir(packet_dir):
            if fname.lower() == "usaspending_awards.json":
                awards_file = os.path.join(packet_dir, fname)
                break

    awards_data = []
    if os.path.exists(awards_file):
        with open(awards_file, 'r', encoding='utf-8') as f:
            awards_data = json.load(f, parse_float=Decimal, parse_int=Decimal)

    awards_by_id = {}
    for award in awards_data:
        keys = set()
        gen_id = award.get("generated_unique_award_id")
        if gen_id:
            keys.add(gen_id)
        aid = award.get("id")
        if aid is not None:
            keys.add(str(aid))
        for k in keys:
            awards_by_id.setdefault(k, []).append(award)

    result = {}
    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    for pair in pairs:
        if "::" in pair:
            rule_id, entity = pair.split("::", 1)
        else:
            rule_id, entity = "", pair

        fact_names = facts_by_rule.get(rule_id, [])
        pair_result = {}

        matching_awards = awards_by_id.get(entity, [])

        for fact_name in fact_names:
            cfg = FACT_CONFIG.get(fact_name)
            if not cfg:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name = cfg["doc"]
            field_path = cfg["path"]
            fact_type = cfg["type"]

            values = []
            for aw in matching_awards:
                raw_val = get_nested(aw, field_path)
                if fact_type == "date":
                    formatted = format_date(raw_val)
                elif fact_type == "amount":
                    formatted = format_amount(raw_val)
                else:
                    formatted = str(raw_val) if raw_val is not None else None

                if formatted is not None:
                    values.append(formatted)

            if not values:
                pair_result[fact_name] = "ABSENT"
            else:
                is_conflict = False
                first_val = values[0]
                for other_val in values[1:]:
                    if fact_type == "amount":
                        if not amounts_equal(first_val, other_val):
                            is_conflict = True
                            break
                    elif fact_type == "date":
                        if not dates_equal(first_val, other_val):
                            is_conflict = True
                            break
                    else:
                        if first_val != other_val:
                            is_conflict = True
                            break

                if is_conflict:
                    pair_result[fact_name] = "CONFLICT"
                else:
                    pair_result[fact_name] = [first_val, doc_name]

        result[pair] = pair_result

    print(json.dumps(result, indent=1))


if __name__ == "__main__":
    main()
