import sys
import json
import os
from decimal import Decimal


def get_fact_extractor(fact_name):
    if fact_name == "performance start":
        return ("usaspending_awards", "date", lambda a: (a.get("period_of_performance") or {}).get("start_date"))
    elif fact_name == "performance end":
        return ("usaspending_awards", "date", lambda a: (a.get("period_of_performance") or {}).get("end_date"))
    elif fact_name == "amount obligated":
        return ("usaspending_awards", "amount", lambda a: a.get("total_obligation"))
    elif fact_name == "potential value":
        return ("usaspending_awards", "amount", lambda a: a.get("base_and_all_options"))
    return None


def sanitize_value(val, val_type):
    if val is None:
        return None
    if val_type == "date":
        if not isinstance(val, str):
            return None
        val_str = val.strip()
        if not val_str:
            return None
        # Extract YYYY-MM-DD
        date_part = val_str.split()[0].split("T")[0]
        return date_part
    elif val_type == "amount":
        if isinstance(val, str) and not val.strip():
            return None
        try:
            return Decimal(str(val))
        except Exception:
            return None
    return str(val)


def format_value(val, val_type):
    if val_type == "amount":
        return str(val)
    return str(val)


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Find usaspending_awards.json
    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    if not os.path.exists(awards_file):
        for root, _, files in os.walk(packet_dir):
            if "usaspending_awards.json" in files:
                awards_file = os.path.join(root, "usaspending_awards.json")
                break

    awards_data = []
    if os.path.exists(awards_file):
        with open(awards_file, "r", encoding="utf-8") as f:
            awards_data = json.load(f, parse_float=Decimal, parse_int=Decimal)

    # Index awards by generated_unique_award_id
    awards_by_guid = {}
    awards_by_id = {}
    for award in awards_data:
        guid = award.get("generated_unique_award_id")
        if guid:
            awards_by_guid.setdefault(guid, []).append(award)
        aid = award.get("id")
        if aid is not None:
            awards_by_id.setdefault(str(aid), []).append(award)

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        fact_names = facts_by_rule.get(rule_id, [])

        matching_awards = awards_by_guid.get(entity)
        if matching_awards is None:
            matching_awards = awards_by_id.get(entity, [])

        pair_result = {}

        for fact_name in fact_names:
            extractor_info = get_fact_extractor(fact_name)
            if not extractor_info:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name, val_type, extractor = extractor_info

            distinct_values = []
            for award in matching_awards:
                raw_val = extractor(award)
                clean_val = sanitize_value(raw_val, val_type)
                if clean_val is not None:
                    if not any(clean_val == existing for existing in distinct_values):
                        distinct_values.append(clean_val)

            if len(distinct_values) == 0:
                pair_result[fact_name] = "ABSENT"
            elif len(distinct_values) == 1:
                val_str = format_value(distinct_values[0], val_type)
                pair_result[fact_name] = [val_str, doc_name]
            else:
                pair_result[fact_name] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()
