    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    awards_data = []
    if os.path.exists(awards_file):
        with open(awards_file, "r", encoding="utf-8") as f:
            awards_data = json.load(f, parse_float=Decimal, parse_int=Decimal)

    # Group awards by generated_unique_award_id
    records_by_entity = {}
    for item in awards_data:
        entity_id = item.get("generated_unique_award_id")
        if entity_id:
            records_by_entity.setdefault(str(entity_id), []).append(item)

    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity_id = pair.split("::", 1)
        facts = facts_spec.get(rule_id, [])
        pair_output = {}

        records = records_by_entity.get(entity_id, [])

