                    for r in records:
                        pop = r.get("period_of_performance")
                        if isinstance(pop, dict):
                            val = pop.get("start_date")
                            if val:
                                vals.append(str(val)[:10])
                    if not vals:
                        pair_output[fact] = "ABSENT"
                    elif any(v != vals[0] for v in vals):
                        pair_output[fact] = "CONFLICT"
                    else:
                        pair_output[fact] = [vals[0], "usaspending_awards"]

