                    vals = []
                    for r in records:
                        pop = r.get("period_of_performance")
                        if isinstance(pop, dict):
                            val = pop.get("end_date")
                            if val:
                                vals.append(str(val)[:10])
                    if not vals:
                        pair_output[fact] = "ABSENT"
                    elif any(v != vals[0] for v in vals):
                        pair_output[fact] = "CONFLICT"
                    else:
                        pair_output[fact] = [vals[0], "usaspending_awards"]
                else:
                    pair_output[fact] = "ABSENT"

            elif rule_id == "usa.obligated_95":
                if fact == "amount obligated":
                    vals = []
                    for r in records:
                        val = r.get("total_obligation")
                        if val is not None:
                            vals.append(val)
                    if not vals:
                        pair_output[fact] = "ABSENT"
                    else:
                        dec_vals = [Decimal(str(v)) for v in vals]
                        if any(dv != dec_vals[0] for dv in dec_vals):
                            pair_output[fact] = "CONFLICT"
                        else:
                            pair_output[fact] = [str(vals[0]), "usaspending_awards"]

                elif fact == "potential value":
                    vals = []
                    for r in records:
                        val = r.get("base_and_all_options")
                        if val is not None:
                            vals.append(val)
                    if not vals:
                        pair_output[fact] = "ABSENT"
                    else:
                        dec_vals = [Decimal(str(v)) for v in vals]
                        if any(dv != dec_vals[0] for dv in dec_vals):
                            pair_output[fact] = "CONFLICT"
                        else:
                            pair_output[fact] = [str(vals[0]), "usaspending_awards"]
                else:
                    pair_output[fact] = "ABSENT"
            else:
                pair_output[fact] = "ABSENT"

        output[pair] = pair_output

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
