import sys
import os
import json
from decimal import Decimal
from collections import defaultdict

def find_file(directory, filename):
    target = os.path.join(directory, filename)
    if os.path.exists(target):
        return target
    for root, _, files in os.walk(directory):
        if filename in files:
            return os.path.join(root, filename)
    return None

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    awards_file = find_file(packet_dir, "usaspending_awards.json")
    awards_by_id = defaultdict(list)

    if awards_file and os.path.exists(awards_file):
        with open(awards_file, "r", encoding="utf-8") as f:
            awards_data = json.load(f, parse_float=Decimal, parse_int=Decimal)
            if isinstance(awards_data, list):
                for award in awards_data:
                    award_id = award.get("generated_unique_award_id")
                    if award_id:
                        awards_by_id[award_id].append(award)

    fact_extractors = {
        "performance start": {
            "doc": "usaspending_awards",
            "type": "date",
            "extract": lambda r: (r.get("period_of_performance") or {}).get("start_date")
        },
        "performance end": {
            "doc": "usaspending_awards",
            "type": "date",
            "extract": lambda r: (r.get("period_of_performance") or {}).get("end_date")
        },
        "amount obligated": {
            "doc": "usaspending_awards",
            "type": "amount",
            "extract": lambda r: r.get("total_obligation")
        },
        "potential value": {
            "doc": "usaspending_awards",
            "type": "amount",
            "extract": lambda r: r.get("base_and_all_options")
        }
    }

    results = {}
    pairs = manifest.get("pairs", [])
    rule_facts = manifest.get("facts", {})

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity_id = pair.split("::", 1)
        facts = rule_facts.get(rule_id, [])

        pair_result = {}
        records = awards_by_id.get(entity_id, [])

        for fact in facts:
            info = fact_extractors.get(fact)
            if not info:
                pair_result[fact] = "ABSENT"
                continue

            doc_name = info["doc"]
            val_type = info["type"]
            extract_fn = info["extract"]

            values = []
            for rec in records:
                raw_val = extract_fn(rec)
                if raw_val is not None and raw_val != "":
                    values.append(raw_val)

            if not values:
                pair_result[fact] = "ABSENT"
            elif val_type == "date":
                formatted_dates = [str(v).strip()[:10] for v in values]
                if len(set(formatted_dates)) == 1:
                    pair_result[fact] = [formatted_dates[0], doc_name]
                else:
                    pair_result[fact] = "CONFLICT"
            elif val_type == "amount":
                try:
                    dec_values = [Decimal(str(v)) for v in values]
                    if all(d == dec_values[0] for d in dec_values):
                        pair_result[fact] = [str(values[0]), doc_name]
                    else:
                        pair_result[fact] = "CONFLICT"
                except Exception:
                    if len(set(str(v) for v in values)) == 1:
                        pair_result[fact] = [str(values[0]), doc_name]
                    else:
                        pair_result[fact] = "CONFLICT"
            else:
                str_values = [str(v) for v in values]
                if len(set(str_values)) == 1:
                    pair_result[fact] = [str_values[0], doc_name]
                else:
                    pair_result[fact] = "CONFLICT"

        results[pair] = pair_result

    print(json.dumps(results, indent=1))

if __name__ == "__main__":
    main()
