import sys
import os
import json
import re
from decimal import Decimal


def get_nested(d, keys):
    curr = d
    for k in keys:
        if isinstance(curr, dict):
            curr = curr.get(k)
        else:
            return None
    return curr


def format_date(val):
    if val is None:
        return None
    val_str = str(val).strip()
    if not val_str or val_str.lower() == "null":
        return None
    m = re.match(r"^(\d{4}-\d{2}-\d{2})", val_str)
    if m:
        return m.group(1)
    m2 = re.match(r"^(\d{1,2})/(\d{1,2})/(\d{4})", val_str)
    if m2:
        m_month, d_day, y_year = m2.groups()
        return f"{int(y_year):04d}-{int(m_month):02d}-{int(d_day):02d}"
    return val_str


def format_amount(val):
    if val is None:
        return None
    val_str = str(val).strip()
    if not val_str or val_str.lower() == "null":
        return None
    val_clean = val_str.replace("$", "").replace(",", "")
    try:
        d = Decimal(val_clean)
        return format(d, "f")
    except Exception:
        return val_clean


def values_conflict(v1, v2, val_type):
    if val_type == "amount":
        try:
            return Decimal(v1) != Decimal(v2)
        except Exception:
            return v1 != v2
    return v1 != v2


RULES = {
    "usa.period_3y": {
        "performance start": (
            "usaspending_awards",
            lambda r: get_nested(r, ["period_of_performance", "start_date"]),
            "date",
        ),
        "performance end": (
            "usaspending_awards",
            lambda r: get_nested(r, ["period_of_performance", "end_date"]),
            "date",
        ),
    },
    "usa.obligated_95": {
        "amount obligated": (
            "usaspending_awards",
            lambda r: r.get("total_obligation"),
            "amount",
        ),
        "potential value": (
            "usaspending_awards",
            lambda r: r.get("base_and_all_options"),
            "amount",
        ),
    },
}

FACT_FALLBACK = {
    "performance start": (
        "usaspending_awards",
        lambda r: get_nested(r, ["period_of_performance", "start_date"]),
        "date",
    ),
    "performance end": (
        "usaspending_awards",
        lambda r: get_nested(r, ["period_of_performance", "end_date"]),
        "date",
    ),
    "amount obligated": (
        "usaspending_awards",
        lambda r: r.get("total_obligation"),
        "amount",
    ),
    "potential value": (
        "usaspending_awards",
        lambda r: r.get("base_and_all_options"),
        "amount",
    ),
}


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    awards_by_id = {}
    if os.path.exists(awards_file):
        with open(awards_file, "r", encoding="utf-8") as f:
            raw_data = json.load(f, parse_float=str, parse_int=str)
            if isinstance(raw_data, list):
                awards_list = raw_data
            elif isinstance(raw_data, dict):
                awards_list = raw_data.get("results", [raw_data])
            else:
                awards_list = []

            for item in awards_list:
                aid = item.get("generated_unique_award_id")
                if aid:
                    awards_by_id.setdefault(aid, []).append(item)

    results = {}
    pairs = manifest.get("pairs", [])
    manifest_facts = manifest.get("facts", {})

    for pair in pairs:
        if "::" in pair:
            rule_id, entity_id = pair.split("::", 1)
        else:
            rule_id, entity_id = pair, ""

        facts_to_query = manifest_facts.get(rule_id, [])
        pair_result = {}

        for fact_name in facts_to_query:
            rule_spec = RULES.get(rule_id, {}).get(fact_name)
            if not rule_spec:
                rule_spec = FACT_FALLBACK.get(fact_name)

            if not rule_spec:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name, extractor, val_type = rule_spec

            if doc_name == "usaspending_awards":
                records = awards_by_id.get(entity_id, [])
            else:
                records = []

            if not records:
                pair_result[fact_name] = "ABSENT"
                continue

            extracted_vals = []
            for r in records:
                val = extractor(r)
                if val is not None:
                    if val_type == "date":
                        formatted_val = format_date(val)
                    elif val_type == "amount":
                        formatted_val = format_amount(val)
                    else:
                        formatted_val = str(val)

                    if formatted_val is not None:
                        extracted_vals.append(formatted_val)

            if not extracted_vals:
                pair_result[fact_name] = "ABSENT"
            else:
                has_conflict = False
                for i in range(len(extracted_vals)):
                    for j in range(i + 1, len(extracted_vals)):
                        if values_conflict(
                            extracted_vals[i], extracted_vals[j], val_type
                        ):
                            has_conflict = True
                            break
                    if has_conflict:
                        break

                if has_conflict:
                    pair_result[fact_name] = "CONFLICT"
                else:
                    pair_result[fact_name] = [extracted_vals[0], doc_name]

        results[pair] = pair_result

    print(json.dumps(results, indent=1))


if __name__ == "__main__":
    main()
