        if "::" in pair:
            rule_id, entity_id = pair.split("::", 1)
        else:
            rule_id, entity_id = pair, ""

        facts_to_query = manifest_facts.get(rule_id, [])
        pair_result = {}

        for fact_name in facts_to_query:
            rule_spec = RULES.get(rule_id, {}).get(fact_name)
            if not rule_spec:
                rule_spec = FACT_FALLBACK.get(fact_name)

            if not rule_spec:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name, extractor, val_type = rule_spec

            if doc_name == "usaspending_awards":
                records = awards_by_id.get(entity_id, [])
            else:
                records = []

            if not records:
                pair_result[fact_name] = "ABSENT"
                continue

            extracted_vals = []
            for r in records:
                val = extractor(r)
                if val is not None:
                    if val_type == "date":
                        formatted_val = format_date(val)
                    elif val_type == "amount":
                        formatted_val = format_amount(val)
                    else:
                        formatted_val = str(val)

                    if formatted_val is not None:
                        extracted_vals.append(formatted_val)

            if not extracted_vals:
                pair_result[fact_name] = "ABSENT"
            else:
                has_conflict = False
                for i in range(len(extracted_vals)):
                    for j in range(i + 1, len(extracted_vals)):
                        if values_conflict(
                            extracted_vals[i], extracted_vals[j], val_type
                        ):
                            has_conflict = True
                            break
                    if has_conflict:
                        break

                if has_conflict:
                    pair_result[fact_name] = "CONFLICT"
                else:
                    pair_result[fact_name] = [extracted_vals[0], doc_name]

        results[pair] = pair_result

    print(json.dumps(results, indent=1))


if __name__ == "__main__":
    main()

